/* append one hop to a counted history field */
static bool hop_add(history_t *h, const char *name, uint64_t at_ms) {
    size_t n = strlen(name), need = h->len + 4 + n + 8;
    if (need > HISTORY_CAP) return false;          /* bound the history */
    unsigned char *p = h->buf + h->len;
    uint32_t len = (uint32_t)n;
    memcpy(p, &len, 4); p += 4;
    memcpy(p, name, n); p += n;
    memcpy(p, &at_ms, 8); p += 8;
    h->len = (size_t)(p - h->buf);
    return true;
}
